import{c as t,Q as a,j as s,m as r}from"./chunks/framework.BqPkuuVc.js";const u=JSON.parse('{"title":"Relay events","description":"","frontmatter":{},"headers":[],"relativePath":"user/event-setup/relay-events.md","filePath":"user/event-setup/relay-events.md"}'),n={name:"user/event-setup/relay-events.md"};function o(i,e,l,d,h,g){return a(),s("div",null,[...e[0]||(e[0]=[r('<h1 id="relay-events" tabindex="-1">Relay events <a class="header-anchor" href="#relay-events" aria-label="Permalink to &quot;Relay events&quot;">​</a></h1><p><strong>Audience:</strong> Event organisers and timing operators running a relay competition.</p><p>A <em>relay</em> is a team event: one team entry is run by several people in sequence, one per <em>leg</em>, each handing over to the next. Manager treats a relay as a first-class event type from creation through to results and export. This page is the full picture — how a relay differs from an individual event, how to set one up, build and import teams, run the day, and read the results.</p><blockquote><p><strong>Status:</strong> Draft — covers current behaviour. A few areas are still evolving (see <a href="#not-yet-supported">What isn&#39;t supported yet</a>).</p></blockquote><hr><h2 id="how-a-relay-differs-from-an-individual-event" tabindex="-1">How a relay differs from an individual event <a class="header-anchor" href="#how-a-relay-differs-from-an-individual-event" aria-label="Permalink to &quot;How a relay differs from an individual event&quot;">​</a></h2><p>Almost everything you already know about running an event still applies. The relay-specific differences are concentrated in a few places:</p><table tabindex="0"><thead><tr><th>Area</th><th>Individual event</th><th>Relay event</th></tr></thead><tbody><tr><td><strong>Event type</strong></td><td>Individual</td><td>Relay — chosen at creation, <strong>fixed for the life of the event</strong></td></tr><tr><td><strong>Entry</strong></td><td>One competitor</td><td>One <strong>team</strong>, made of leg runners</td></tr><tr><td><strong>Class</strong></td><td>One course pool</td><td>Same, but the class has a <strong>number of legs</strong> (2 or more)</td></tr><tr><td><strong>Start</strong></td><td>Drawn, allocated, or punched</td><td><strong>Mass start</strong> per class; punched starts are ignored</td></tr><tr><td><strong>Bibs</strong></td><td>Free-form, per competitor</td><td>Team carries the base bib; each leg&#39;s bib is <strong>derived</strong> as <code>{teamBib}.{leg}</code></td></tr><tr><td><strong>Result</strong></td><td>Finish − start</td><td>Composed from the legs: per-leg times, a team total, and a team status</td></tr><tr><td><strong>Ranking</strong></td><td>By race time / projected time</td><td>By legs completed and progress; finished teams by team time</td></tr><tr><td><strong>Export</strong></td><td>One file</td><td>Scoped to <strong>relay</strong> or <strong>individual</strong> classes — never both in one file</td></tr></tbody></table><p>A relay event can also hold ordinary individual classes alongside the relay classes — see <a href="#mixed-events-relay-and-individual-classes-together">Mixed events</a>.</p><blockquote><p><strong>New to the terms?</strong> A <em>leg</em> is one runner&#39;s portion of the relay; the <em>changeover</em> is the handover from one leg to the next. See the <a href="./../getting-started/concepts-glossary#relays-and-teams">glossary</a>.</p></blockquote><hr><h2 id="creating-a-relay-event" tabindex="-1">Creating a relay event <a class="header-anchor" href="#creating-a-relay-event" aria-label="Permalink to &quot;Creating a relay event&quot;">​</a></h2><h3 id="from-scratch" tabindex="-1">From scratch <a class="header-anchor" href="#from-scratch" aria-label="Permalink to &quot;From scratch&quot;">​</a></h3><p>Click <strong>New Event</strong> on the <a href="./create-event">Events page</a>. A small <strong>New Event</strong> dialog asks the event type:</p><ul><li><strong>Individual</strong> — an ordinary event.</li><li><strong>Relay</strong> — reveals a <strong>Number of legs</strong> field (default <strong>3</strong>, minimum 2). This becomes the default leg count for the relay classes you create; each class can use a different count.</li></ul><p>Pick <strong>Relay</strong>, set the number of legs, and click <strong>Create</strong>. Manager creates the event in <strong>Setup</strong> mode and opens it at its dashboard.</p><blockquote><p><strong>Warning:</strong> The event type is <strong>immutable</strong> once the event exists — you cannot convert an individual event into a relay or vice versa. Switching would invalidate the event&#39;s classes and teams, so Manager doesn&#39;t allow it. If you picked the wrong type, create a new event.</p></blockquote><h3 id="from-eventor" tabindex="-1">From Eventor <a class="header-anchor" href="#from-eventor" aria-label="Permalink to &quot;From Eventor&quot;">​</a></h3><p>When you <a href="./create-event-from-eventor">create an event from Eventor</a>, the import dialog has an <strong>event type</strong> step of its own. Manager reads the Eventor event form and pre-selects the type — an Eventor <strong>relay</strong> event (single- or multi-day relay form) suggests <strong>Relay</strong>, anything else <strong>Individual</strong> — and you confirm or change it before the event is created. Choosing <strong>Relay</strong> here also asks for the event&#39;s default <strong>Number of legs</strong>.</p><blockquote><p><strong>Note:</strong> Some clubs run a relay where each runner enters <em>individually</em> rather than as a pre-formed team (Eventor sends individual entries, not team entries). Eventor&#39;s payload doesn&#39;t flag this as a relay — Manager can only guess from the event&#39;s name — so check the pre-selected type rather than trusting it. You then mark which classes are actually relays at the class review step — see <a href="#importing-teams">Importing teams</a>.</p></blockquote><h3 id="the-relay-settings-on-the-event" tabindex="-1">The relay settings on the event <a class="header-anchor" href="#the-relay-settings-on-the-event" aria-label="Permalink to &quot;The relay settings on the event&quot;">​</a></h3><p>Open the event details (edit icon on the <strong>Event header</strong> card) to review two relay-relevant settings:</p><ul><li><strong>Default relay legs</strong> — the leg count new relay classes are seeded with. Changing it doesn&#39;t retroactively change existing classes; it only affects classes created afterwards.</li><li>On the <strong>Starts</strong> tab, the mass-start switch is locked on with the note <em>&quot;Relay events are always mass start.&quot;</em> Set the event&#39;s <strong>Mass Start Time</strong> here — any relay class that doesn&#39;t have a mass-start time of its own falls back to it (below).</li><li>Also on the <strong>Starts</strong> tab, an optional <strong>Restart</strong> time sets the event-wide <a href="#restarts-omstart">restart (omstart)</a>. Every relay class inherits it as its restart unless the class sets its own time or opts out — exactly the way the mass start is inherited.</li></ul><hr><h2 id="relay-classes" tabindex="-1">Relay classes <a class="header-anchor" href="#relay-classes" aria-label="Permalink to &quot;Relay classes&quot;">​</a></h2><p>A relay class is just a class with <strong>two or more legs</strong>. You create and edit classes the same way as in an individual event (see <a href="./classes-and-courses">Classes and courses</a>) — the relay-specific controls live in the <strong>Edit Class</strong> dialog.</p><h3 id="relay-or-individual-the-class-kind" tabindex="-1">Relay or individual (the class kind) <a class="header-anchor" href="#relay-or-individual-the-class-kind" aria-label="Permalink to &quot;Relay or individual (the class kind)&quot;">​</a></h3><p>In a relay event each class is either a <strong>relay</strong> class or an <strong>individual</strong> side class. The <strong>Edit Class</strong> dialog shows a <strong>Class type</strong> chooser (Relay / Individual):</p><ul><li><strong>Relay</strong> reveals <strong>Number of legs</strong> — the number of runners in a team for this class. The minimum is <strong>2</strong> (&quot;Relay classes have at least 2 legs.&quot;).</li><li><strong>Individual</strong> turns the class into an ordinary single-leg class run alongside the relay — &quot;normal starts, bibs and individual results&quot;.</li></ul><blockquote><p><strong>Note:</strong> The class type chooser only appears in a <strong>relay event</strong>. In an individual event every class is single-leg and there&#39;s nothing to choose.</p></blockquote><p>Manager decides &quot;is this a relay class?&quot; purely from the leg count: <strong>more than one leg means relay</strong>. There&#39;s no separate hidden flag to get out of step with the number you see.</p><h3 id="number-of-legs" tabindex="-1">Number of legs <a class="header-anchor" href="#number-of-legs" aria-label="Permalink to &quot;Number of legs&quot;">​</a></h3><ul><li>New relay classes start at the event&#39;s <strong>Default relay legs</strong>.</li><li>You can set any count of <strong>2 or more</strong> per class — classes in the same event can have different leg counts.</li><li>Setting a class to <strong>1 leg</strong> makes it an individual side class.</li></ul><h3 id="changing-a-class-s-kind" tabindex="-1">Changing a class&#39;s kind <a class="header-anchor" href="#changing-a-class-s-kind" aria-label="Permalink to &quot;Changing a class&#39;s kind&quot;">​</a></h3><ul><li><strong>Individual → Relay:</strong> allowed any time; set the leg count.</li><li><strong>Relay → Individual:</strong> <strong>refused while the class still has teams.</strong> Delete the class&#39;s teams first, then change it. (Teams can only belong to a relay class — Manager won&#39;t let a team sit on a single-leg class.)</li><li><strong>Changing a relay class&#39;s leg count</strong> (say 3 → 4) is allowed even with teams, but the teams are <strong>not resized</strong> to match. A team whose roster doesn&#39;t match the class&#39;s leg count can&#39;t be classified — it stays unranked until you edit each team and fill (or remove) the legs. Manager recomputes the class&#39;s teams immediately when you save the change.</li></ul><hr><h2 id="courses-and-forked-legs" tabindex="-1">Courses and forked legs <a class="header-anchor" href="#courses-and-forked-legs" aria-label="Permalink to &quot;Courses and forked legs&quot;">​</a></h2><p>A relay class holds a <strong>course pool</strong> exactly like an individual class — one row per physical course. Relay legs are very often run on <strong>forked</strong> (gaffled) course variants, so a class typically has several courses in its pool, one per variant.</p><p>There are two ways a leg runner ends up on the right course:</p><ol><li><strong>Course locks by bib and leg.</strong> If your course-setting software exports per-runner course assignments in its IOF course file, Manager imports them as <strong>course locks</strong> — each leg runner is pinned to their assigned course. Runners are matched by <strong>bib number</strong>, so import the start/entry list (which carries the bibs) <em>before</em> the course file. See <a href="./classes-and-courses#course-pools-and-locking-a-competitor-to-a-course">Locking a competitor to a course</a>.</li><li><strong>In the team dialog.</strong> When you build a team by hand you can pick each leg&#39;s <strong>Course</strong> (and its <strong>Variation</strong>, if the course has forks) directly — see <a href="#building-teams-by-hand">Building teams</a>.</li></ol><p>If a leg isn&#39;t locked to a course, Manager checks the runner&#39;s download against <strong>every</strong> course in the class pool and keeps the best match — the same pooled behaviour as an individual class.</p><blockquote><p><strong>Note:</strong> Manager does <strong>not</strong> check that a team runs each fork exactly once across its legs. Balancing the gaffles is the course-setter&#39;s job; Manager applies whatever assignment it&#39;s given.</p></blockquote><h3 id="radio-controls-per-leg" tabindex="-1">Radio controls per leg <a class="header-anchor" href="#radio-controls-per-leg" aria-label="Permalink to &quot;Radio controls per leg&quot;">​</a></h3><p>Radio controls in a relay are configured on the <strong>class</strong>, tagged by leg — leg 1&#39;s radio controls are separate from leg 2&#39;s, even where the physical control code is the same. On the live surfaces (Leaderboard, Spectator screens) Manager compares teams only at the radio controls their courses genuinely share — matched by control code and visit number, not by position — so forked legs still compare fairly. Each competitor&#39;s own non-shared radio splits stay visible in <strong>Manager</strong> and <strong>Commentary</strong>. See <a href="./controls-and-radio-controls">Controls and radio controls</a>.</p><hr><h2 id="start-times-for-relays" tabindex="-1">Start times for relays <a class="header-anchor" href="#start-times-for-relays" aria-label="Permalink to &quot;Start times for relays&quot;">​</a></h2><p>Relay start timing is simpler than individual timing, because the model is fixed:</p><ul><li><strong>Every relay class starts by mass start.</strong> The whole field in a class sets off together at the class&#39;s mass-start time. Set it in <strong>Edit Class</strong> (the dialog notes &quot;Relay classes start by mass start; punched starts are ignored&quot;). A class with no mass-start time of its own falls back to the event&#39;s mass start; give a class its own time to stagger it.</li><li><strong>Punched starts are ignored</strong> for relay legs. A runner punching a Start unit doesn&#39;t change their timing — the class mass start is always the anchor.</li><li>Every leg is timed from that one mass start <code>S</code>. That&#39;s what makes the <a href="#how-relay-results-are-calculated">results maths</a> work: a runner&#39;s clock is the time since <code>S</code>, and the per-leg times fall out as the differences between successive finishes.</li></ul><p>To stagger classes (a <em>wave</em> start), give each class its own mass-start time — 10:00 for one, 10:15 for the next. See <a href="./start-times">Start times</a> for the mass-start controls in general.</p><h3 id="restarts-omstart" tabindex="-1">Restarts (omstart) <a class="header-anchor" href="#restarts-omstart" aria-label="Permalink to &quot;Restarts (omstart)&quot;">​</a></h3><p>Large relays almost always <strong>restart</strong> waiting runners at a cutoff time, so a team whose incoming runner is very late isn&#39;t left standing indefinitely. Manager supports this at the event level with a per-class override — the same shape as the mass start:</p><ul><li><p><strong>Set it once for the whole event.</strong> On the event&#39;s <strong>Starts</strong> tab, set a <strong>Restart</strong> time. Every relay class inherits it, so a single cutoff applied to the whole field takes one setting.</p></li><li><p><strong>Override or opt out per class.</strong> In <strong>Edit Class</strong>, a relay class can either set its <strong>own Restart</strong> time (which wins over the event restart) or, when it has no restart of its own, tick <strong>&quot;Exclude this class from the event restart&quot;</strong> so it never restarts even though the event does — useful for an elite class you want to leave running. A class with neither shows the inherited event time it will use.</p></li><li><p>At the effective restart time <code>R</code>, <strong>every runner still waiting</strong> starts together. A leg&#39;s start is therefore whichever is earlier: its normal changeover, or the restart. In the maths, <code>start_i = min(changeover_i, R)</code>.</p></li><li><p>The team&#39;s <strong>official total is the sum of its leg times</strong>, each leg timed from its own start (a restarted leg from <code>R</code>, not from the late changeover). When every changeover was normal this is exactly finish-minus-mass-start. When a leg was restarted it is <strong>larger</strong> than the wall-clock finish-minus-mass-start — because the restarted runner overlapped the still-out incoming runner, and the sum-of-legs counts that runner&#39;s full time on course, which the wall clock would otherwise hide. This is the whole reason the total is summed from the legs rather than read off the finish clock.</p><blockquote><p><strong>Worked example.</strong> Mass start 10:00. Leg 1 runs 10:00→10:30 (<strong>30 min</strong>); leg 2 runs 10:30→12:30 (<strong>2 h</strong>); leg 3&#39;s runner is still waiting at the 12:00 restart (leg 2 hasn&#39;t arrived), so they start at 12:00 and run to 13:00 (<strong>1 h</strong>). Team total = 30 min + 2 h + 1 h = <strong>3 h 30 min</strong> — not the 3 h you&#39;d read straight off the 10:00→13:00 finish clock, because leg 3 and leg 2 were on course together between 12:00 and 12:30.</p></blockquote></li></ul><p>Declaring or changing a restart time — at either level — <strong>immediately recomputes</strong> every affected team — you don&#39;t need to re-download anything.</p><blockquote><p><strong>Note:</strong> A restart time that is at or before the class mass start can&#39;t be applied (it would put a waiting runner before the start) — Manager ignores it and logs a warning. If a restart you set has no visible effect, check that its time is genuinely <em>after</em> the class mass start and that the class actually has a resolvable mass start.</p></blockquote><blockquote><p><strong>Warning:</strong> Live ordering of teams <em>while a restart is in effect</em> is approximate — the live ranking compares wall-clock punch times, which a restart deliberately breaks. The <strong>finished</strong> team totals are exact; only the in-progress ordering of restarted teams is a best-effort estimate.</p></blockquote><hr><h2 id="building-teams-by-hand" tabindex="-1">Building teams (by hand) <a class="header-anchor" href="#building-teams-by-hand" aria-label="Permalink to &quot;Building teams (by hand)&quot;">​</a></h2><p>Open the <strong>Teams</strong> page (in the event&#39;s data nav) and choose <strong>Actions → Add Team</strong>, or click an existing team&#39;s name to edit it. The <strong>Add/Edit Relay Team</strong> dialog has:</p><table tabindex="0"><thead><tr><th>Field</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Team Name</strong></td><td>The team&#39;s name (required).</td></tr><tr><td><strong>Bib</strong></td><td>The team&#39;s base start number. Each leg runner&#39;s bib is derived from it (see <a href="#team-bibs">Bibs</a>).</td></tr><tr><td><strong>Class</strong></td><td>The relay class the team runs in — the picker only offers relay classes. You must pick the class before you can assign runners.</td></tr><tr><td><strong>Club</strong></td><td>The team&#39;s club (optional).</td></tr><tr><td><strong>Legs</strong></td><td>One row per leg: the <strong>Runner</strong> (picked from the competitors in the team&#39;s class), plus a <strong>Course</strong> picker when the class has a course pool and a <strong>Variation</strong> picker when the chosen course has forks.</td></tr><tr><td><strong>Official team</strong></td><td>On by default — &quot;eligible for official placings and awards&quot;. Turn off for a composite / out-of-club team that races but shouldn&#39;t take an official placing (see <a href="#official-and-unofficial-teams">Official vs unofficial</a>).</td></tr><tr><td><strong>Photo finish — judged order</strong></td><td>Only appears when this team is tied with another on exactly equal totals — drag the tied teams into the judge&#39;s finishing order (see <a href="#photo-finishes-judged-order">Photo finishes</a>).</td></tr></tbody></table><p>The number of leg rows follows the class&#39;s leg count. You can save a <strong>partially-built</strong> team — leave a leg&#39;s runner unset and fill it in later; the empty slot still holds its leg position.</p><blockquote><p><strong>Note:</strong> A runner must be a competitor <strong>in the team&#39;s class</strong> to appear in the Runner picker. Import or add the competitors first, then build the teams.</p></blockquote><h3 id="the-unique-runner-rule" tabindex="-1">The unique-runner rule <a class="header-anchor" href="#the-unique-runner-rule" aria-label="Permalink to &quot;The unique-runner rule&quot;">​</a></h3><p>A relay team&#39;s members are distinct people: <strong>a competitor may run at most one leg, of at most one team.</strong></p><ul><li>A roster that puts the same runner on two legs is rejected (&quot;The same competitor cannot run more than one leg.&quot;).</li><li>A runner already on another team can&#39;t be added to a second — Manager names the clashing team.</li></ul><p>This is enforced everywhere teams are written — the dialog, and every import path — so a roster that breaks the rule is never saved. Because runners are unique, a runner&#39;s <strong>position in the roster is their leg number</strong> (row 1 = leg 1), with no ambiguity.</p><h3 id="team-bibs" tabindex="-1">Team bibs <a class="header-anchor" href="#team-bibs" aria-label="Permalink to &quot;Team bibs&quot;">​</a></h3><p>In a relay event, bibs work top-down from the team:</p><ul><li>You set the team&#39;s <strong>base bib</strong> (e.g. <code>42</code>) in the team dialog.</li><li>Manager derives each leg runner&#39;s bib automatically as <code>{teamBib}.{leg}</code> — <code>42.1</code>, <code>42.2</code>, <code>42.3</code> — and keeps them in sync whenever you change the roster or the base bib. A runner removed from a team has their derived bib cleared.</li><li>A leg runner&#39;s bib is therefore <strong>read-only</strong> in the <strong>Edit Competitor</strong> dialog for a relay event. That dialog shows the runner&#39;s <strong>Relay team</strong> panel instead — their team name, leg, bib, and start time — all read-only. To change a relay runner&#39;s bib, change the <strong>team&#39;s</strong> bib.</li><li>To clear a team&#39;s bib entirely, empty the <strong>Bib</strong> field and save; the members&#39; derived bibs clear with it. (An <em>empty</em> bib arriving from a re-import is treated as &quot;no information&quot; and leaves the existing bib untouched — a re-import never wipes a bib you&#39;ve set.)</li></ul><h3 id="when-you-can-edit-teams" tabindex="-1">When you can edit teams <a class="header-anchor" href="#when-you-can-edit-teams" aria-label="Permalink to &quot;When you can edit teams&quot;">​</a></h3><p>Team editing is for <strong>before the start</strong> — create teams, assign runners to legs, reorder or clear legs. <strong>Mid-race substitutions, reserves, and re-ordering legs after the start are not supported yet</strong> (see <a href="#not-yet-supported">What isn&#39;t supported yet</a>).</p><p>To delete a team, open it and use the <strong>Delete</strong> button in the edit dialog.</p><blockquote><p><strong>Note:</strong> Deleting a <em>competitor</em> who sits on a team doesn&#39;t delete the team. The leg&#39;s runner shows as missing (—) and the team drops back to in-progress — it can&#39;t be classified until you repair the roster in <strong>Edit Team</strong>.</p></blockquote><hr><h2 id="importing-teams" tabindex="-1">Importing teams <a class="header-anchor" href="#importing-teams" aria-label="Permalink to &quot;Importing teams&quot;">​</a></h2><p>You rarely want to build a full field of teams by hand. What each import route gives you:</p><h3 id="from-eventor-1" tabindex="-1">From Eventor <a class="header-anchor" href="#from-eventor-1" aria-label="Permalink to &quot;From Eventor&quot;">​</a></h3><p>When importing from Eventor into a relay event, the <strong>class review</strong> step lets you mark <strong>each class</strong> as <strong>Relay</strong> or <strong>Individual</strong> (&quot;Mark each class as part of the relay or as an individual side class run alongside it.&quot;). This is where you resolve the individually-entered-relay case: even though Eventor sends individual entries, you tell Manager which classes are actually relays. Where Eventor knows a class&#39;s leg count, the toggle shows it as a hint (&quot;<em>N</em> legs in Eventor&quot;) and the class keeps it; otherwise a class you mark Relay gets the event&#39;s default leg count — adjust it per class in the class editor afterwards. You then form the teams — build them in the <a href="#building-teams-by-hand">team dialog</a>, or, if the entries carry <code>team.leg</code> bibs, re-import them as an <a href="#from-an-iof-entry-list-the-bib-convention">IOF entry list</a> so the bib convention assembles them.</p><p>Your per-class choices are remembered across re-imports — a class you marked <strong>Individual</strong> stays individual when you re-import, and won&#39;t be silently turned back into a relay.</p><h3 id="from-an-iof-entry-list-the-bib-convention" tabindex="-1">From an IOF entry list (the bib convention) <a class="header-anchor" href="#from-an-iof-entry-list-the-bib-convention" aria-label="Permalink to &quot;From an IOF entry list (the bib convention)&quot;">​</a></h3><p>An IOF <strong>entry list</strong> import doesn&#39;t yet read structured team entries. Instead Manager assembles teams from the <strong>bib convention</strong>: entries whose bibs follow the <code>team.leg</code> pattern (<code>42.1</code>, <code>42.2</code>, <code>42.3</code>) are grouped into one team (base bib <code>42</code>) with the leg numbers taken from the suffix. Manager reports how many teams it assembled, and warns about any malformed group (a lone runner, a gap or duplicate in the leg sequence) rather than stitching runners onto the wrong legs. See <a href="./import-event-data#entry-list-iof-entrylist-xml">Entry list import</a>.</p><h3 id="from-an-iof-file-with-no-designation-step" tabindex="-1">From an IOF file with no designation step <a class="header-anchor" href="#from-an-iof-file-with-no-designation-step" aria-label="Permalink to &quot;From an IOF file with no designation step&quot;">​</a></h3><p>An IOF file import has no class-review step, so in a relay event Manager <strong>treats every imported class as a relay class</strong> and warns you, naming each adjusted class. Flip any genuine individual side classes back to <strong>Individual</strong> in the class editor afterwards — the warning tells you exactly which classes to check. (Classes you&#39;ve already set to Individual stay individual on a re-import.)</p><blockquote><p><strong>Tip:</strong> Whichever route you use, glance at the <strong>Teams</strong> page and the import warnings afterward. A missing runner, a wrong leg count, or a class that should have been individual all show up there.</p></blockquote><hr><h2 id="running-the-event" tabindex="-1">Running the event <a class="header-anchor" href="#running-the-event" aria-label="Permalink to &quot;Running the event&quot;">​</a></h2><p>On the day, each leg is an ordinary card-download and radio-punch flow — with a few relay specifics.</p><h3 id="one-card-per-leg-shared-and-hire-cards" tabindex="-1">One card per leg; shared and hire cards <a class="header-anchor" href="#one-card-per-leg-shared-and-hire-cards" aria-label="Permalink to &quot;One card per leg; shared and hire cards&quot;">​</a></h3><p>Each leg runner carries their own card and produces their <strong>own download</strong> after their leg. Different runners on a team may <strong>reuse the same physical card</strong> across legs (common with hire cards), so the same card number can appear in several of a team&#39;s downloads.</p><p>Because a card number isn&#39;t unique within a team, Manager can&#39;t assign a shared-card download by card number alone. Instead, a runner who already has a download (or a final result) keeps it, and a new read of the same card goes to the next runner on that card who doesn&#39;t have one yet — preferring a runner who is still out on course. In practice: <strong>read the legs in the order they ran</strong> and each download lands on the right runner. If reads arrive out of order, check the assignments and move a download from the download history if needed. See <a href="./../running-the-event/card-download">Downloading cards</a> and <a href="./../running-the-event/hire-items">Hire items</a>.</p><h3 id="radio-punches-and-provisional-results" tabindex="-1">Radio punches and provisional results <a class="header-anchor" href="#radio-punches-and-provisional-results" aria-label="Permalink to &quot;Radio punches and provisional results&quot;">​</a></h3><p>Radio punches are tagged to the leg that produced them and feed the live team position. When the <strong>final leg&#39;s radio finish</strong> arrives — before the card is downloaded — the team shows a <strong>provisional</strong> result (an OK/time marked provisional, the same convention as an individual provisional-OK: the team is exported with that leg overridden to DNF and no leg time, so no unconfirmed total is published). The final result replaces it once the leg&#39;s card downloads. See <a href="./../running-the-event/radio-punches">Radio punches</a>.</p><blockquote><p><strong>Note:</strong> A radio punch carries only its card number, so when several team members share one card, Manager gives a live punch to the member it believes is currently on course. If that guess is ever wrong (unusual leg overlap, a restart), the live picture self-corrects as the cards are downloaded — the downloads are authoritative.</p></blockquote><h3 id="a-leg-runner-s-own-time" tabindex="-1">A leg runner&#39;s own time <a class="header-anchor" href="#a-leg-runner-s-own-time" aria-label="Permalink to &quot;A leg runner&#39;s own time&quot;">​</a></h3><p>A leg runner&#39;s stored race time is the team <strong>cumulative</strong> (time since the mass start) — that&#39;s the aggregation model&#39;s input. On individual-facing surfaces (the competitor list&#39;s race-time column in a relay event) Manager shows the runner&#39;s <strong>own leg time</strong> instead, so a leg-3 runner&#39;s column reads their leg, not the whole team&#39;s elapsed time.</p><hr><h2 id="how-relay-results-are-calculated" tabindex="-1">How relay results are calculated <a class="header-anchor" href="#how-relay-results-are-calculated" aria-label="Permalink to &quot;How relay results are calculated&quot;">​</a></h2><h3 id="leg-times-and-the-changeover" tabindex="-1">Leg times and the changeover <a class="header-anchor" href="#leg-times-and-the-changeover" aria-label="Permalink to &quot;Leg times and the changeover&quot;">​</a></h3><p>Let <code>S</code> be the class mass start and <code>Fᵢ</code> leg <em>i</em>&#39;s finish time of day:</p><table tabindex="0"><thead><tr><th>Quantity</th><th>How it&#39;s computed</th></tr></thead><tbody><tr><td>Leg 1 time</td><td><code>F₁ − S</code></td></tr><tr><td>Leg <em>i</em> time (<em>i</em> &gt; 1)</td><td><code>Fᵢ − Fᵢ₋₁</code> — from the previous runner&#39;s finish (the changeover)</td></tr><tr><td>Team total</td><td><code>Fₙ − S</code> — equivalently, the <strong>sum of all leg times</strong></td></tr></tbody></table><p>Because every leg is anchored at the same mass start, these telescope: the leg times always add up to the team total. A restart changes a leg&#39;s start to the restart time where that&#39;s earlier (above), and the total stays the sum of leg times.</p><blockquote><p><strong>Note:</strong> If corrupt or mis-edited data would make a leg&#39;s finish land <em>before</em> the previous one, Manager <strong>breaks the changeover chain</strong> for that leg rather than showing a negative split. A leg time never goes negative on the results.</p></blockquote><h3 id="when-a-leg-fails" tabindex="-1">When a leg fails <a class="header-anchor" href="#when-a-leg-fails" aria-label="Permalink to &quot;When a leg fails&quot;">​</a></h3><ul><li><strong>No restart declared:</strong> a leg with no finish (DNF/MP) <strong>stops the chain</strong> — that leg and every leg after it get no time (radio splits may still record). The team can&#39;t classify anyway (below).</li><li><strong>Restart declared:</strong> a waiting leg <strong>anchors at the restart</strong> instead of stalling, so later legs still get times. The team still can&#39;t be classified until every leg finishes OK.</li></ul><h3 id="classification-and-team-status" tabindex="-1">Classification and team status <a class="header-anchor" href="#classification-and-team-status" aria-label="Permalink to &quot;Classification and team status&quot;">​</a></h3><ul><li><strong>Team status is the worst of its legs.</strong> Any leg MP makes the team MP; any DNF makes the team DNF; the team is <strong>OK only when every leg is OK</strong>.</li><li><strong>A team is classified (rankable) only when it has run the full number of legs and every leg is OK.</strong> A team missing a leg, or with any non-OK leg, isn&#39;t ranked and shows no team total.</li></ul><h3 id="live-ranking-of-in-progress-teams" tabindex="-1">Live ranking of in-progress teams <a class="header-anchor" href="#live-ranking-of-in-progress-teams" aria-label="Permalink to &quot;Live ranking of in-progress teams&quot;">​</a></h3><p>While teams are still out, Manager orders them by:</p><ol><li><strong>Legs completed</strong> (OK finishes) — more is better;</li><li>then the <strong>furthest shared radio control</strong> reached on the current leg;</li><li>then the <strong>earliest</strong> wall-clock time at that control.</li></ol><p>This uses only controls the teams genuinely share, so it stays correct under forked legs, and it degrades gracefully when radio coverage is sparse. Finished teams rank by their team total; unclassified teams sink below them.</p><blockquote><p><strong>Note:</strong> Relay classes show <strong>no projected finish times</strong> — not for the team, and not for its leg runners. Don&#39;t look for the projected-time column you&#39;d see in an individual class; the live order comes from the shared radio controls instead.</p></blockquote><h3 id="behind-times-and-split-rankings" tabindex="-1">Behind times and split rankings <a class="header-anchor" href="#behind-times-and-split-rankings" aria-label="Permalink to &quot;Behind times and split rankings&quot;">​</a></h3><p>Per-leg <strong>behind times</strong> and <strong>split rankings</strong> compare each leg runner only against the <em>same leg</em> at the <em>same control</em>. Because splits are cumulative from the mass start, a split ranking on legs 2+ reflects the <strong>team&#39;s aggregate position</strong> at that control (which team is winning) rather than that runner&#39;s isolated leg pace — the right question to ask live. Cross-runner leg-pace comparison (&quot;the fastest third leg of the day&quot;) is a post-race analysis Manager doesn&#39;t compute today.</p><h3 id="photo-finishes-judged-order" tabindex="-1">Photo finishes (judged order) <a class="header-anchor" href="#photo-finishes-judged-order" aria-label="Permalink to &quot;Photo finishes (judged order)&quot;">​</a></h3><p>Where two classified teams finish on <strong>exactly</strong> equal totals, the chip time can&#39;t separate them — IOF rules say the <strong>finishing order across the line</strong> decides the placing. Record the judge&#39;s call in the team dialog: open any of the tied teams, and a <strong>Photo finish — judged order</strong> section appears listing the tied teams — drag them into the order they crossed the line. Manager then gives them <strong>distinct placings</strong> in that order. The judged order:</p><ul><li><strong>can never overrule a faster time</strong> — it only breaks an exact tie (the section only appears when a tie exists);</li><li>survives re-imports (an import can&#39;t wipe your call);</li><li>if you don&#39;t record one, equal-time teams simply <strong>share</strong> a placing.</li></ul><h3 id="official-and-unofficial-teams" tabindex="-1">Official and unofficial teams <a class="header-anchor" href="#official-and-unofficial-teams" aria-label="Permalink to &quot;Official and unofficial teams&quot;">​</a></h3><p>A team marked <strong>not official</strong> (Edit Team) still races, still shows its result, and still sorts by its time — but it takes <strong>no official placing</strong> and doesn&#39;t consume a placing number. Official placings close over it: if an unofficial team would have been 2nd, the next official team is 2nd, not 3rd. Use this for composite or out-of-club teams that run for interest.</p><hr><h2 id="mixed-events-relay-and-individual-classes-together" tabindex="-1">Mixed events: relay and individual classes together <a class="header-anchor" href="#mixed-events-relay-and-individual-classes-together" aria-label="Permalink to &quot;Mixed events: relay and individual classes together&quot;">​</a></h2><p>A relay event may contain both relay classes and ordinary individual classes — an open or enter-on-the-day class run on the same day belongs in the relay event, not a separate one. The rules:</p><ul><li>Each class is designated <strong>Relay</strong> or <strong>Individual</strong> (at Eventor import, or in the class editor).</li><li>Individual side classes behave exactly like classes in an individual event: editable per-competitor bibs, allocated/imported/punched start times, and eligibility for the <strong><a href="./start-draw">start draw</a></strong> (which only ever draws individual classes — it skips relay classes).</li><li><strong>Exports never mix the two kinds.</strong> When you export results, a start list or an <a href="./competitors-clubs-teams#exporting-the-entry-list">entry list</a> — or upload to Eventor — from a mixed event, Manager asks which kind the file should contain (relay or individual). A file only ever holds one kind.</li><li><strong>On-screen</strong> surfaces (Results, Leaderboard, Commentary, official results) happily show both, rendering each class according to its kind.</li></ul><hr><h2 id="where-relays-appear" tabindex="-1">Where relays appear <a class="header-anchor" href="#where-relays-appear" aria-label="Permalink to &quot;Where relays appear&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Surface</th><th>What it shows for relays</th></tr></thead><tbody><tr><td><strong>Results</strong></td><td>One row per team in each relay class — place, team, club and total time, with provisional results marked <code>*</code>. No per-leg breakdown here yet; use the Leaderboard or Commentary for per-leg columns.</td></tr><tr><td><strong>Teams page</strong></td><td>The working list: team, bib, class, club, members, start time, radio times, status and the official flag — columns you can reorder and hide.</td></tr><tr><td><strong>Leaderboard</strong></td><td>Live team ordering with per-leg finish columns and the team total, rendered from Manager&#39;s computed leg data.</td></tr><tr><td><strong><a href="./../screens/commentary">Commentary</a></strong></td><td>Team classes route to a relay result table; each runner&#39;s own splits stay visible in the feed.</td></tr><tr><td><strong><a href="./../screens/tv-screens">Spectator TV</a></strong></td><td>A team summary row — the members (current runner highlighted with ▶), and the total; a team still racing shows which leg it&#39;s on. (A full per-leg spectator breakdown is still to come.)</td></tr></tbody></table><hr><h2 id="not-yet-supported" tabindex="-1">Not yet supported <a class="header-anchor" href="#not-yet-supported" aria-label="Permalink to &quot;Not yet supported&quot;">​</a></h2><p>These are known gaps — plan around them:</p><ul><li><strong>Mid-race changes.</strong> Substituting a runner, adding a reserve, or reordering legs <strong>after the start</strong> isn&#39;t supported. Build and correct teams before the mass start.</li><li><strong>Structured IOF team entries and start lists.</strong> The IOF <code>TeamEntry</code>/<code>TeamStart</code> elements are neither read nor written — team assembly on import relies on the <a href="#from-an-iof-entry-list-the-bib-convention">bib convention</a>, and a relay start-list export lists each leg runner individually rather than as team entries.</li><li><strong>IOF results import.</strong> Manager exports IOF relay results but doesn&#39;t import them — you can&#39;t rebuild a relay&#39;s teams and times from another system&#39;s results file.</li><li><strong>Per-leg breakdown in the Results view.</strong> The manager Results page shows one row per team; per-leg columns exist only on the Leaderboard and Commentary tables so far.</li><li><strong>Multi-day / stage relays.</strong> A multi-day relay&#39;s individual days work normally, but times <strong>carried forward</strong> between stages aren&#39;t modelled.</li><li><strong>Patrol / group (&quot;Team&quot;) events</strong> — where members run <em>together</em> with no per-leg changeover — are a separate, not-yet-built scenario. Everything on this page is about ordered-leg relays.</li><li><strong>Full spectator per-leg breakdown</strong> and <strong>post-race per-leg pace analysis</strong> are still to come.</li></ul><hr><h2 id="common-mistakes" tabindex="-1">Common mistakes <a class="header-anchor" href="#common-mistakes" aria-label="Permalink to &quot;Common mistakes&quot;">​</a></h2><ul><li><strong>Picked the wrong event type.</strong> The type is fixed at creation — you can&#39;t convert. Create a new event.</li><li><strong>A class that should be individual is being treated as a relay.</strong> After an IOF file import (or if you missed it at Eventor import), open the class and set it to <strong>Individual</strong>. The import warning names the classes to check.</li><li><strong>Can&#39;t turn a relay class individual.</strong> It still has teams — delete the class&#39;s teams first.</li><li><strong>Editing a relay runner&#39;s bib doesn&#39;t stick.</strong> Relay bibs are derived from the team. Change the <strong>team&#39;s</strong> bib instead.</li><li><strong>A restart has no effect.</strong> Its time must be <em>after</em> the class mass start, and the class must have a resolvable mass start. A restart at/before the mass start is ignored.</li><li><strong>Teams won&#39;t rank.</strong> A team is only classified once it has run <em>every</em> leg and all legs are <strong>OK</strong> — one MP or DNF leg keeps the whole team unranked. The same happens when a team&#39;s roster doesn&#39;t match the class&#39;s leg count (after a leg-count change) or a leg&#39;s runner was deleted — repair the roster in <strong>Edit Team</strong>.</li><li><strong>Export refuses / asks which classes.</strong> A mixed event can&#39;t export both kinds at once — choose relay or individual for the file.</li><li><strong>Bib assembly warnings on import.</strong> Entry-list team assembly needs clean <code>team.leg</code> bibs. A gap, duplicate, or lone runner is reported rather than guessed — fix the bibs and re-import.</li></ul><hr><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./classes-and-courses">Classes and courses</a> — creating classes and courses, course pools, course locks</li><li><a href="./controls-and-radio-controls">Controls and radio controls</a> — per-leg radio configuration</li><li><a href="./start-times">Start times</a> — mass starts and how start times resolve</li><li><a href="./competitors-clubs-teams">Competitors and clubs</a> — editing an individual leg runner</li><li><a href="./import-event-data">Importing event data</a> — IOF and Eventor imports</li><li><a href="./create-event-from-eventor">Creating an event from Eventor</a> — the Eventor relay flow</li><li><a href="./../running-the-event/card-download">Downloading cards</a> and <a href="./../running-the-event/hire-items">Hire items</a> — shared-card downloads</li><li><a href="./../running-the-event/radio-punches">Radio punches</a> — live punches and provisional results</li><li><a href="./../after-the-event/results">Results</a> and <a href="./../after-the-event/exports">Exporting data</a> — reading and exporting team results</li><li><a href="./../reference/status-and-race-time">Status and race time rules</a> — the status values behind worst-leg propagation</li><li><a href="./../getting-started/concepts-glossary#relays-and-teams">Concepts and glossary</a> — relay terminology</li></ul>',134)])])}const m=t(n,[["render",o]]);export{u as __pageData,m as default};
